function plusMinusDigits(n: number): number {
  let sum = 0, sign = 1, count = 0;
  while (n > 0) {
    sum += sign * (n % 10);
    sign = -sign;
    count++;
    n = Math.floor(n / 10);
  }
  return count % 2 === 0 ? -sum : sum;
}

